CREATE SET TABLE MDP01_META.META_DATATYPE_MAPPING ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      mapping_id INTEGER NOT NULL,      source_system VARCHAR(50) CHARACTER SET UNICODE NOT CASESPECIFIC NOT NULL,      source_datatype VARCHAR(100) CHARACTER SET UNICODE NOT CASESPECIFIC NOT NULL,      source_max_length INTEGER,      source_precision INTEGER,      source_scale INTEGER,      target_datatype VARCHAR(100) CHARACTER SET UNICODE NOT CASESPECIFIC NOT NULL,      target_max_length INTEGER,      target_precision INTEGER,      target_scale INTEGER,      target_character_set VARCHAR(50) CHARACTER SET UNICODE NOT CASESPECIFIC,      requires_cast BYTEINT NOT NULL DEFAULT 0 ,      cast_expression VARCHAR(500) CHARACTER SET UNICODE NOT CASESPECIFIC,      data_loss_risk VARCHAR(10) CHARACTER SET UNICODE NOT CASESPECIFIC,      conversion_notes VARCHAR(1000) CHARACTER SET UNICODE NOT CASESPECIFIC,      example_source_value VARCHAR(200) CHARACTER SET UNICODE NOT CASESPECIFIC,      example_target_value VARCHAR(200) CHARACTER SET UNICODE NOT CASESPECIFIC,      is_active BYTEINT NOT NULL DEFAULT 1 ,      created_by VARCHAR(100) CHARACTER SET UNICODE NOT CASESPECIFIC DEFAULT 'SYSTEM',      created_timestamp TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),      last_updated_by VARCHAR(100) CHARACTER SET UNICODE NOT CASESPECIFIC DEFAULT 'SYSTEM',      last_updated_timestamp TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),      tpt_schema_multiplier BYTEINT DEFAULT 1 ,      convert_template VARCHAR(200) CHARACTER SET LATIN NOT CASESPECIFIC,      TYPE_FORMAT_TEMPLATE VARCHAR(100) CHARACTER SET UNICODE NOT CASESPECIFIC)PRIMARY INDEX ( mapping_id )INDEX ( source_system ,source_datatype );